package local.tclbridge;
import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;
public class LocalAdbTest {
 static int checks;
 static void require(boolean b){if(!b)throw new AssertionError();checks++;}
 static class Packet {int c,a,b;byte[] data;}
 static Packet read(InputStream in)throws Exception{byte[] h=new byte[24];new DataInputStream(in).readFully(h);ByteBuffer b=ByteBuffer.wrap(h).order(ByteOrder.LITTLE_ENDIAN);Packet p=new Packet();p.c=b.getInt();p.a=b.getInt();p.b=b.getInt();int n=b.getInt();b.getInt();require(b.getInt()==(p.c^0xffffffff));require(n>=0&&n<20000);p.data=new byte[n];new DataInputStream(in).readFully(p.data);return p;}
 static void send(OutputStream out,int c,int a,int b,byte[] d)throws Exception{int sum=0;for(byte x:d)sum+=x&255;byte[] h=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN).putInt(c).putInt(a).putInt(b).putInt(d.length).putInt(sum).putInt(c^0xffffffff).array();out.write(h,0,5);out.write(h,5,19);out.write(d);out.flush();}
 static void handshake(Socket s)throws Exception{Packet cn=read(s.getInputStream());require(cn.c==LocalAdb.CNXN);byte[] token=new byte[20];Arrays.fill(token,(byte)7);send(s.getOutputStream(),LocalAdb.AUTH,1,0,token);Packet sig=read(s.getInputStream());require(sig.c==LocalAdb.AUTH&&sig.a==2&&sig.data.length==256);send(s.getOutputStream(),LocalAdb.AUTH,1,0,token);Packet pub=read(s.getInputStream());require(pub.c==LocalAdb.AUTH&&pub.a==3);String p=new String(pub.data,"UTF-8");require(p.endsWith(" alexa-na-tv@localhost\0"));byte[] key=Base64.getDecoder().decode(p.split(" ")[0]);require(key.length==524);send(s.getOutputStream(),LocalAdb.CNXN,0x01000000,4096,"device::\0".getBytes("UTF-8"));}
 interface ServerAction{void run(Socket s)throws Exception;}
 static void scenario(ServerAction server,java.util.function.Consumer<LocalAdb> client)throws Exception{try(ServerSocket ss=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){ExecutorService e=Executors.newSingleThreadExecutor();Future<?> f=e.submit(()->{try(Socket s=ss.accept()){s.setSoTimeout(5000);server.run(s);}catch(Exception x){throw new RuntimeException(x);}});try(LocalAdb adb=new LocalAdb(ss.getLocalPort())){client.accept(adb);f.get(8,TimeUnit.SECONDS);}finally{e.shutdownNow();}}}
 public static void main(String[] args)throws Exception{
  scenario(s->{handshake(s);Packet open=read(s.getInputStream());require(open.c==LocalAdb.OPEN);require(new String(open.data,"UTF-8").contains("shell:( id )"));send(s.getOutputStream(),LocalAdb.OKAY,1,open.a,new byte[0]);send(s.getOutputStream(),LocalAdb.WRTE,1,open.a,"hello\n".getBytes("UTF-8"));require(read(s.getInputStream()).c==LocalAdb.OKAY);send(s.getOutputStream(),LocalAdb.WRTE,1,open.a,"\n__TCLBRIDGE_EXIT__0\n".getBytes("UTF-8"));require(read(s.getInputStream()).c==LocalAdb.OKAY);send(s.getOutputStream(),LocalAdb.CLSE,1,open.a,new byte[0]);send(s.getOutputStream(),LocalAdb.CLSE,1,open.a,new byte[0]);Packet second=read(s.getInputStream());require(second.c==LocalAdb.OPEN&&second.a>open.a);send(s.getOutputStream(),LocalAdb.OKAY,2,second.a,new byte[0]);send(s.getOutputStream(),LocalAdb.WRTE,2,second.a,"next\n__TCLBRIDGE_EXIT__0\n".getBytes("UTF-8"));require(read(s.getInputStream()).c==LocalAdb.OKAY);send(s.getOutputStream(),LocalAdb.CLSE,2,second.a,new byte[0]);},a->{try{a.connect(m->{});require(a.shell("id").equals("hello"));require(a.shell("id").equals("next"));}catch(Exception e){throw new RuntimeException(e);}});
  for(int size:new int[]{-1,1048577})scenario(s->{read(s.getInputStream());byte[] h=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN).putInt(LocalAdb.CNXN).putInt(0).putInt(4096).putInt(size).putInt(0).putInt(LocalAdb.CNXN^0xffffffff).array();s.getOutputStream().write(h);s.getOutputStream().flush();},a->{try{a.connect(m->{});throw new AssertionError();}catch(IOException expected){require(true);}catch(Exception e){throw new RuntimeException(e);}});
  scenario(s->{read(s.getInputStream());s.getOutputStream().write(new byte[24]);s.getOutputStream().flush();},a->{try{a.connect(m->{});throw new AssertionError();}catch(IOException expected){require(true);}catch(Exception e){throw new RuntimeException(e);}});
  scenario(s->{handshake(s);Packet o=read(s.getInputStream());send(s.getOutputStream(),LocalAdb.OKAY,1,o.a,new byte[0]);send(s.getOutputStream(),LocalAdb.WRTE,1,o.a,"denied\n__TCLBRIDGE_EXIT__1\n".getBytes("UTF-8"));read(s.getInputStream());send(s.getOutputStream(),LocalAdb.CLSE,1,o.a,new byte[0]);},a->{try{a.connect(m->{});a.shell("id");throw new AssertionError();}catch(IOException expected){require(true);}catch(Exception e){throw new RuntimeException(e);}});
  System.out.println("LocalAdb: 5 cenários passaram; "+checks+" verificações (autorização, shell fragmentado, limites, integridade, falha de comando).");
 }
}
